-- 1. SEED FARMERS
INSERT INTO "farmers" ("id", "slug", "name", "farmName", "photo", "cover", "bio", "story", "methods", "certifications", "region", "town", "pickupGPS", "location", "farmToHubRadiusKm", "rating", "reviewCount", "baselineRating", "baselineReviewCount", "joinedYear", "onTimeRate", "kycStatus")
VALUES ('f1', 'auntie-ama', 'Auntie Ama Owusu', 'Ama''s Garden', '/golden-acres/farmers/auntie-ama.jpg', NULL, 'Third-generation vegetable grower famous for the sweetest Roma tomatoes in the Eastern Region.', 'Auntie Ama has farmed the same red-earth plot outside Koforidua for over thirty years, a craft passed down from her grandmother. She still hand-picks every tomato at dawn so it reaches the hub before the heat of the day. “A tomato remembers how it was treated,” she likes to say. Her beds are rotated with legumes each season to keep the soil alive without heavy chemicals.', '["Hand-harvested at dawn","Crop rotation","Drip irrigation","Low-spray"]'::jsonb, '["GhanaGAP Certified"]'::jsonb, 'Eastern', 'Koforidua', 'EN-052-8841', '{"lat":6.094,"lng":-0.2597}'::jsonb, 85, 4.9, 212, 4.9, 212, 2021, 0.97, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
INSERT INTO "farmers" ("id", "slug", "name", "farmName", "photo", "cover", "bio", "story", "methods", "certifications", "region", "town", "pickupGPS", "location", "farmToHubRadiusKm", "rating", "reviewCount", "baselineRating", "baselineReviewCount", "joinedYear", "onTimeRate", "kycStatus")
VALUES ('f2', 'kwame-mensah', 'Kwame Mensah', 'Mensah Family Farm', '/golden-acres/farmers/kwame-mensah.jpg', NULL, 'Roots-and-tubers specialist growing yam, plantain and cassava on family land in Ejisu.', 'Kwame left a logistics job in Kumasi to take over his family’s farm in Ejisu, bringing a planner’s discipline to the harvest calendar. He grades every yam tuber by hand and cures plantain in shade so it ripens evenly on the journey to Accra. His farm employs eight people from his village year-round.', '["Shade-cured plantain","Hand-graded tubers","Manual weeding"]'::jsonb, '[]'::jsonb, 'Ashanti', 'Ejisu', 'AK-389-1120', '{"lat":6.711,"lng":-1.466}'::jsonb, 250, 4.7, 148, 4.7, 148, 2022, 0.94, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
INSERT INTO "farmers" ("id", "slug", "name", "farmName", "photo", "cover", "bio", "story", "methods", "certifications", "region", "town", "pickupGPS", "location", "farmToHubRadiusKm", "rating", "reviewCount", "baselineRating", "baselineReviewCount", "joinedYear", "onTimeRate", "kycStatus")
VALUES ('f3', 'esi-boateng', 'Esi Boateng', 'Green Leaf Collective', '/golden-acres/farmers/esi-boateng.jpg', NULL, 'Young agronomist leading a women-run collective growing crisp leafy greens near Prampram.', 'Esi studied agronomy at Legon and returned home to organise twelve women growers into the Green Leaf Collective. They specialise in the most fragile, fast-spoiling greens — lettuce, cabbage and kontomire — which is exactly why cold-chain delivery matters so much to them. Harvest happens the same morning your order is packed.', '["Same-day harvest","Shade-net nurseries","Women-led collective"]'::jsonb, '["Certified Organic"]'::jsonb, 'Greater Accra', 'Prampram', 'GA-447-2098', '{"lat":5.715,"lng":0.099}'::jsonb, 40, 4.8, 176, 4.8, 176, 2023, 0.98, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
INSERT INTO "farmers" ("id", "slug", "name", "farmName", "photo", "cover", "bio", "story", "methods", "certifications", "region", "town", "pickupGPS", "location", "farmToHubRadiusKm", "rating", "reviewCount", "baselineRating", "baselineReviewCount", "joinedYear", "onTimeRate", "kycStatus")
VALUES ('f4', 'yaw-darko', 'Yaw Darko', 'Darko Organics', '/golden-acres/farmers/yaw-darko.jpg', NULL, 'Certified-organic grower of okra, aubergine and chillies in the lush Volta hills.', 'Yaw converted his family plots near Ho to full organic certification in 2020, betting that Accra’s kitchens would pay for produce grown without synthetic chemicals. He composts on-site and uses neem as his only pest control. His okra is picked young and tender every other day.', '["Fully organic","On-site compost","Neem pest control","Pick-every-other-day"]'::jsonb, '["Certified Organic","GhanaGAP Certified"]'::jsonb, 'Volta', 'Ho', 'VH-110-7765', '{"lat":6.611,"lng":0.471}'::jsonb, 170, 4.9, 121, 4.9, 121, 2022, 0.95, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
