VALUES ('f5', 'adwoa-sarpong', 'Adwoa Sarpong', 'Sunrise Fields', '/golden-acres/farmers/adwoa-sarpong.jpg', NULL, 'Large-acreage grower of onions, maize and beans in the breadbasket town of Techiman.', 'Adwoa runs one of the larger family operations in Bono, supplying staples that store well and travel far. She invested in solar-powered storage so her onions and beans reach market without waste. She mentors younger farmers on record-keeping and fair pricing.', '["Solar-powered storage","Furrow irrigation","Record-kept yields"]'::jsonb, '["GhanaGAP Certified"]'::jsonb, 'Bono', 'Techiman', 'BT-901-4432', '{"lat":7.583,"lng":-1.938}'::jsonb, 340, 4.6, 98, 4.6, 98, 2023, 0.92, 'verified')
