VALUES ('f7', 'mahama-sulemana', 'Mahama Sulemana', 'Savannah Grains', '/golden-acres/farmers/mahama-sulemana.jpg', NULL, 'Elder cereal farmer cultivating rice, sorghum and millet on the Tamale plains for over fifty years.', 'Old Mahama has read the northern skies for half a century, planting with the first rains and harvesting his rice and sorghum by hand the way his father taught him. “The land is patient, so a farmer must be patient too,” he says. He is one of the most respected elders in his community and is now onboarding with Golden Acres to bring savannah grains to southern kitchens — his first listings arrive next harvest.', '["Rain-fed cultivation","Hand-harvested","Traditional seed-saving","Sun-dried grain"]'::jsonb, '[]'::jsonb, 'Northern', 'Tamale', 'NT-204-6610', '{"lat":9.4008,"lng":-0.8393}'::jsonb, 620, 4.9, 41, 4.9, 41, 2025, 0.93, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
