VALUES ('f8', 'hawa-azumah', 'Hawa Azumah', 'Bolga Women’s Collective', '/golden-acres/farmers/hawa-azumah.jpg', NULL, 'Matriarch leading an Upper East women’s group growing groundnuts, bambara beans and shea.', 'Hawa leads a forty-woman collective outside Bolgatanga that has pooled land and labour for three decades. They grow drought-hardy groundnuts and bambara beans and gather shea nuts from the wild parkland, processing butter the slow traditional way. Joining Golden Acres means a fairer price reaches the women who actually grow the food — their staples list opens this season.', '["Women-led collective","Drought-hardy varieties","Wild-gathered shea","Hand-processed"]'::jsonb, '["Fair-Trade Group"]'::jsonb, 'Upper East', 'Bolgatanga', 'UB-118-3390', '{"lat":10.7856,"lng":-0.8514}'::jsonb, 760, 4.8, 33, 4.8, 33, 2025, 0.91, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
