VALUES ('f9', 'fati-abukari', 'Fati Abukari', 'Sissala Garden', '/golden-acres/farmers/fati-abukari.jpg', NULL, 'Smallholder vegetable grower who cycles her dawn harvest to the Wa collection point each morning.', 'Fati works a tidy irrigated plot in the Sissala district, growing tomatoes, pepper and leafy greens through the dry season. Every morning she loads her harvest onto her bicycle and rides the red-earth road to the collection point before the sun gets high. “Fresh means today, not yesterday,” she insists. She is finalising her first listings with Golden Acres now.', '["Dry-season irrigation","Dawn harvest","Low-spray","Same-day collection"]'::jsonb, '[]'::jsonb, 'Upper West', 'Wa', 'XW-330-7741', '{"lat":10.0607,"lng":-2.5019}'::jsonb, 680, 4.7, 19, 4.7, 19, 2025, 0.9, 'verified')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "farmName" = EXCLUDED."farmName";
