VALUES ('f10', 'adzaho-brothers', 'Selorm & Edem Adzaho', 'Adzaho Brothers Rice', '/golden-acres/farmers/adzaho-brothers.jpg', NULL, 'Two brothers running an irrigated rice paddy in the Volta lowlands, harvested by sickle at peak ripeness.', 'Selorm and Edem inherited their paddy near Weta and run it as a tight two-man operation, cutting the rice by sickle exactly when the heads turn gold. They mill in small batches so the rice reaches you fragrant and fresh rather than sitting in a warehouse. The brothers are joining Golden Acres to sell their aromatic local rice directly — listings coming this milling season.', '["Irrigated paddy","Sickle-harvested at peak","Small-batch milling","No bleaching"]'::jsonb, '[]'::jsonb, 'Volta', 'Weta', 'VW-512-2208', '{"lat":6.1667,"lng":0.95}'::jsonb, 210, 4.8, 27, 4.8, 27, 2025, 0.92, 'verified')
