-- 4. SEED RECIPES
INSERT INTO "recipes" ("id", "name", "image", "time", "productIds", "description", "category", "serves", "difficulty", "ingredients", "steps", "tip")
VALUES ('r1', 'Classic Ghana Jollof', '/golden-acres/recipes/ghana-jollof.png', '45 min', '["p19","p1","p13","p2","p18"]'::jsonb, 'The crown jewel of any Ghanaian gathering — fragrant local Volta rice simmered in a rich tomato, ginger, onion and scotch bonnet stew until every single grain is deeply flavored with that signature smoky party-jollof aroma.', 'Rice & grains', 'Serves 4', 'Medium', '[{"productId":"p19","qty":1,"note":"washed and drained local perfumed rice"},{"productId":"p1","qty":1,"note":"ripe Roma tomatoes, blended smooth"},{"productId":"p13","qty":1,"note":"one for blending, one sliced for frying"},{"productId":"p2","qty":1,"note":"scotch bonnet peppers to taste"},{"productId":"p18","qty":1,"note":"fresh ginger, peeled and blended"}]'::jsonb, '["Blend the fresh tomatoes, half the onions, ginger, and scotch bonnet peppers into a silky aromatic pepper stew base.","Heat vegetable oil in a heavy-bottomed pot and fry the sliced onions until golden brown and caramelized.","Stir in tomato paste and fry for 3 minutes, then pour in the blended stew base and simmer on medium heat until the oil rises to the top.","Season with salt, bay leaves, and curry powder. Pour in meat or vegetable stock, bring to a rolling boil, and stir in the washed Volta rice.","Cover tightly with foil and pot lid, reduce heat to the lowest setting, and let the rice steam for 25–30 minutes until tender and fluffy.","Allow the base to catch slightly for that irresistible authentic party-jollof smokiness before serving hot with fried plantain."]'::jsonb, 'For that signature party-jollof smokiness, let the bottom catch very lightly before the final steam.')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name";
INSERT INTO "recipes" ("id", "name", "image", "time", "productIds", "description", "category", "serves", "difficulty", "ingredients", "steps", "tip")
VALUES ('r2', 'Red-Red with Fried Plantain', '/golden-acres/recipes/red-red.png', '40 min', '["p15","p4","p13","p2","p20"]'::jsonb, 'A beloved Ghanaian black-eyed cowpea stew cooked in spiced red palm oil (dzomi), paired with sweet, golden caramelized fried plantain (kelewele/dodo).', 'Stews & soups', 'Serves 3–4', 'Easy', '[{"productId":"p15","qty":1,"note":"tender cowpeas, soaked overnight"},{"productId":"p4","qty":2,"note":"very ripe plantains, sliced diagonally"},{"productId":"p13","qty":1,"note":"finely diced red onions"},{"productId":"p2","qty":1,"note":"scotch bonnet peppers, crushed"},{"productId":"p20","qty":1,"note":"pure Dzomi red palm oil"}]'::jsonb, '["Boil the soaked cowpeas with a pinch of salt until soft and creamy, then drain while reserving a cup of the bean broth.","Heat Dzomi red palm oil in a saucepan, fry the diced onions and crushed scotch bonnets until fragrant and translucent.","Pour in blended tomato sauce and simmer for 10 minutes until thick and rich.","Fold in the boiled cowpeas and reserved broth, stirring gently, and let simmer on low heat for 12 minutes to absorb all flavors.","Meanwhile, fry the ripe plantain slices in hot oil until deeply golden and caramelized on both sides.","Serve the piping hot red-red topped with a sprinkle of gari alongside the sweet fried plantains."]'::jsonb, 'The riper the plantain, the sweeter the contrast against the savoury beans.')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name";
INSERT INTO "recipes" ("id", "name", "image", "time", "productIds", "description", "category", "serves", "difficulty", "ingredients", "steps", "tip")
VALUES ('r3', 'Kontomire Palava Sauce', '/golden-acres/recipes/kontomire-palava.png', '35 min', '["p9","p3","p2","p13","p20"]'::jsonb, 'Tender cocoyam leaves stewed with garden eggs, melon seeds (agushie), and aromatic red palm oil into a deep, earthy green sauce.', 'Stews & soups', 'Serves 4', 'Medium', '[{"productId":"p9","qty":2,"note":"freshly picked kontomire leaves, washed and shredded"},{"productId":"p3","qty":1,"note":"boiled white garden eggs, roughly mashed"},{"productId":"p2","qty":1,"note":"scotch bonnet peppers, crushed"},{"productId":"p13","qty":1,"note":"sliced red onions"},{"productId":"p20","qty":1,"note":"unrefined Dzomi palm oil"}]'::jsonb, '["Steam the washed kontomire leaves with a pinch of salt for 4 minutes, then drain and squeeze out all excess moisture.","Boil garden eggs until tender, peel the skin, and mash them into a coarse paste.","Heat palm oil in an earthenware asanka or pot, fry onions and crushed peppers until golden and fragrant.","Add blended melon seeds (agushie paste) without stirring for 3 minutes to form soft, savory curds.","Stir in the mashed garden eggs, shredded kontomire, and smoked fish or shrimp.","Simmer on gentle heat for 8 minutes until rich and thick. Serve with boiled yam, plantain, or rice."]'::jsonb, 'Squeeze the boiled leaves well — too much water and the sauce turns thin.')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name";
INSERT INTO "recipes" ("id", "name", "image", "time", "productIds", "description", "category", "serves", "difficulty", "ingredients", "steps", "tip")
VALUES ('r4', 'Garden Egg Stew', '/golden-acres/recipes/garden-egg-stew.png', '30 min', '["p3","p1","p13"]'::jsonb, 'A quick, rustic stew of boiled garden eggs mashed into a fragrant tomato-onion base — simple, satisfying and ready in half an hour.', 'Stews & soups', 'Serves 3', 'Easy', '[{"productId":"p3","qty":2,"note":"boiled until soft"},{"productId":"p1","qty":1,"note":"blended"},{"productId":"p13","qty":1,"note":"sliced"}]'::jsonb, '["Boil the garden eggs until tender, then peel and mash roughly.","Fry sliced onions in oil until soft, then add the blended tomatoes.","Cook the tomato base down until thick and the oil separates.","Stir in the mashed garden eggs, season to taste, and simmer for 8 minutes.","Serve hot with boiled yam, plantain or rice."]'::jsonb, 'A handful of smoked fish stirred in at the end lifts the whole dish.')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name";
INSERT INTO "recipes" ("id", "name", "image", "time", "productIds", "description", "category", "serves", "difficulty", "ingredients", "steps", "tip")
VALUES ('r5', 'Spicy Grilled Corn', '/golden-acres/recipes/grilled-corn.png', '20 min', '["p14","p2","p18"]'::jsonb, 'Roadside-style charred maize brushed with a smoky pepper-ginger glaze — the taste of a Ghanaian evening by the grill.', 'Street food', 'Serves 2', 'Easy', '[{"productId":"p14","qty":2,"note":"husked"},{"productId":"p2","qty":1,"note":"finely ground"},{"productId":"p18","qty":1,"note":"grated, for the glaze"}]'::jsonb, '["Husk the maize and pat dry.","Mix ground scotch bonnet, grated ginger, a little oil and salt into a glaze.","Grill the corn over medium coals, turning often, until charred in spots.","Brush generously with the glaze in the last few minutes of grilling.","Serve hot, traditionally with a wedge of coconut."]'::jsonb, 'No grill? A dry cast-iron pan over high heat gives a great char too.')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name";
INSERT INTO "recipes" ("id", "name", "image", "time", "productIds", "description", "category", "serves", "difficulty", "ingredients", "steps", "tip")
VALUES ('r6', 'Pineapple Ginger Cooler', '/golden-acres/recipes/pineapple-ginger.png', '15 min', '["p16","p18"]'::jsonb, 'A bright, zingy blend of fresh pineapple and ginger — refreshing, naturally sweet and a Ghanaian party favourite.', 'Sides & snacks', 'Makes 1.5L', 'Easy', '[{"productId":"p16","qty":1,"note":"ripe, peeled and chopped"},{"productId":"p18","qty":1,"note":"peeled"}]'::jsonb, '["Blend the pineapple and ginger with a little water until smooth.","Strain through a fine sieve into a jug.","Sweeten to taste and top up with cold water to 1.5 litres.","Chill thoroughly and serve over ice."]'::jsonb, 'Use the pineapple core too — it holds a lot of sweetness.')
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name";

